-- Gold Query
SELECT CAST(SUM(t2.overall_rating) AS REAL) / COUNT(t2.id) FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t1.height > 170 AND SUBSTRING(t2."date", 1, 4) BETWEEN '2010' AND '2015';

/*
Gold Result:
(5.0,)
*/

-- Prediction Query
SELECT AVG(t1.overall_rating) AS average_overall_rating FROM Player_Attributes AS t1 INNER JOIN Player AS t2 ON t1.player_api_id = t2.id WHERE STRFTIME('%Y', t1.date) >= '2010' AND STRFTIME('%Y', t1.date) <= '2015' AND t2.height > 170;

